import java.util.*;
import java.io.*;
import java.math.*;

public class Main {
    static final long MOD = 998244353L;
    static final BigInteger BIG_MOD = BigInteger.valueOf(MOD);

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        long n = sc.nextInt();
        long m = sc.nextInt();
        long l = sc.nextInt();
        long r = sc.nextInt();
        long k = r - l;
        long even = k / 2 + 1;
        long odd = (k + 1) / 2;
        long cells = n * m;
        if (cells % 2 == 1) {
            out.print(BigInteger.valueOf(k + 1).modPow(BigInteger.valueOf(cells), BIG_MOD));
        } else {
            BigInteger a = BigInteger.valueOf(even + odd).modPow(BigInteger.valueOf(cells), BIG_MOD);
            BigInteger b = BigInteger.valueOf(even - odd).modPow(BigInteger.valueOf(cells), BIG_MOD);
            long ans = (a.longValue() + b.longValue()) % MOD;
            ans = ans * ((MOD + 1) / 2) % MOD;
            out.println(ans);
        }
        out.flush();
        sc.close();
    }
}
